// OW-05 c8 / OW-12 c7: "Export PDF" downloads the previewed report as a PDF file
// that opens in common readers. A small PDF 1.4 writer: A4 landscape, wrapped
// table cells, the table header repeated on every page, and "Page n of N".
//
// Text uses embedded Noto Sans subsets (reportPdfFonts.ts, generated by
// scripts/build-report-pdf-fonts.py) as Type 0 / Identity-H fonts, so ₱ and
// other characters outside Latin-1 print as they do on screen, and a ToUnicode
// map keeps the text searchable and copyable.
import { reportMetaLines, formatReportDateTime, type ReportDocument, type ReportTable } from './reportDocument.ts';
import { REPORT_PDF_FONTS, type ReportPdfFont } from './reportPdfFonts.ts';

const PAGE_WIDTH = 842;
const PAGE_HEIGHT = 595;
const MARGIN = 36;
const CONTENT_WIDTH = PAGE_WIDTH - MARGIN * 2;
const BOTTOM = MARGIN + 18; // room for the footer
const CELL_PADDING = 4;

/** Characters the embedded fonts lack: arrows become "->"; other unknown characters print as "?". */
export function pdfSafeText(value: string): string {
  return value
    .replace(/→/g, '->')
    .replace(/[\u00a0\u2007\u202f]/g, ' ');
}

const fontFor = (bold: boolean): ReportPdfFont => (bold ? REPORT_PDF_FONTS.bold : REPORT_PDF_FONTS.regular);

function glyphOf(font: ReportPdfFont, char: string): number {
  return font.cmap[String(char.codePointAt(0))] ?? font.cmap['63'] ?? 0;
}

export function textWidth(text: string, size: number, bold = false): number {
  const font = fontFor(bold);
  let units = 0;
  for (const char of text) units += font.widths[glyphOf(font, char)] ?? 600;
  return (units * size) / 1000;
}

/** Wrap text to a width: explicit line breaks first, then words, then long words by character. */
export function wrapText(text: string, width: number, size: number, bold = false): string[] {
  const lines: string[] = [];
  for (const paragraph of pdfSafeText(text).split('\n')) {
    let line = '';
    for (const word of paragraph.split(/ +/)) {
      const candidate = line ? `${line} ${word}` : word;
      if (textWidth(candidate, size, bold) <= width) {
        line = candidate;
        continue;
      }
      if (line) lines.push(line);
      line = '';
      let piece = '';
      for (const char of word) {
        if (piece && textWidth(piece + char, size, bold) > width) {
          lines.push(piece);
          piece = '';
        }
        piece += char;
      }
      line = piece;
    }
    lines.push(line);
  }
  return lines;
}

const hex4 = (value: number) => value.toString(16).toUpperCase().padStart(4, '0');

/** Text as a hex string of 2-byte glyph ids (Identity-H). */
export function pdfGlyphs(text: string, bold: boolean): string {
  const font = fontFor(bold);
  let out = '<';
  for (const char of pdfSafeText(text)) out += hex4(glyphOf(font, char));
  return `${out}>`;
}

/** A PDF text string (document info) as UTF-16BE with a byte-order mark. */
function pdfTextString(text: string): string {
  let out = '<FEFF';
  for (let index = 0; index < text.length; index += 1) out += hex4(text.charCodeAt(index));
  return `${out}>`;
}

function decodeBase64(value: string): string {
  if (typeof atob === 'function') return atob(value);
  return (globalThis as unknown as { Buffer: { from(value: string, encoding: string): { toString(encoding: string): string } } })
    .Buffer.from(value, 'base64').toString('latin1');
}

/** The PDF objects of one embedded font: Type 0 font, CID font, descriptor, font file, ToUnicode. */
function fontObjects(font: ReportPdfFont, firstId: number, tag: string): string[] {
  const [type0, cidFont, descriptor, fontFile, toUnicode] = [0, 1, 2, 3, 4].map((offset) => firstId + offset);
  const baseFont = `${tag}+${font.name}`;
  const mappings = Object.entries(font.cmap).map(([code, glyph]) => `<${hex4(glyph)}> <${hex4(Number(code))}>`);
  const chunks: string[] = [];
  for (let index = 0; index < mappings.length; index += 100) {
    const chunk = mappings.slice(index, index + 100);
    chunks.push(`${chunk.length} beginbfchar\n${chunk.join('\n')}\nendbfchar`);
  }
  const cmap = [
    '/CIDInit /ProcSet findresource begin', '12 dict begin', 'begincmap',
    '/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def',
    '/CMapName /Adobe-Identity-UCS def', '/CMapType 2 def',
    '1 begincodespacerange', '<0000> <FFFF>', 'endcodespacerange',
    ...chunks,
    'endcmap', 'CMapName currentdict /CMap defineresource pop', 'end', 'end',
  ].join('\n');
  const file = decodeBase64(font.file);
  return [
    `${type0} 0 obj\n<< /Type /Font /Subtype /Type0 /BaseFont /${baseFont} /Encoding /Identity-H /DescendantFonts [${cidFont} 0 R] /ToUnicode ${toUnicode} 0 R >>\nendobj\n`,
    `${cidFont} 0 obj\n<< /Type /Font /Subtype /CIDFontType2 /BaseFont /${baseFont} /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor ${descriptor} 0 R /CIDToGIDMap /Identity /DW 600 /W [0 [${font.widths.join(' ')}]] >>\nendobj\n`,
    `${descriptor} 0 obj\n<< /Type /FontDescriptor /FontName /${baseFont} /Flags 32 /FontBBox [${font.bbox.join(' ')}] /ItalicAngle 0 /Ascent ${font.ascent} /Descent ${font.descent} /CapHeight ${font.capHeight} /StemV ${font.name.endsWith('Bold') ? 140 : 80} /FontFile2 ${fontFile} 0 R >>\nendobj\n`,
    `${fontFile} 0 obj\n<< /Length ${file.length} /Length1 ${font.length1} /Filter /FlateDecode >>\nstream\n${file}\nendstream\nendobj\n`,
    `${toUnicode} 0 obj\n<< /Length ${cmap.length} >>\nstream\n${cmap}\nendstream\nendobj\n`,
  ];
}

const n = (value: number) => (Math.round(value * 100) / 100).toString();

type Color = [number, number, number];
const INK: Color = [0.063, 0.063, 0.153];
const MUTED: Color = [0.42, 0.42, 0.48];
const PINK: Color = [0.91, 0.2, 0.43];
const RULE: Color = [0.87, 0.87, 0.9];
const HEAD_FILL: Color = [0.953, 0.953, 0.961];

class PdfLayout {
  pages: string[][] = [];
  y = 0;
  private readonly doc: ReportDocument;
  constructor(doc: ReportDocument) {
    this.doc = doc;
    this.newPage(true);
  }

  private get ops(): string[] {
    return this.pages[this.pages.length - 1];
  }

  newPage(first = false): void {
    this.pages.push([]);
    this.y = PAGE_HEIGHT - MARGIN;
    if (!first) {
      this.text(`${this.doc.title} (continued)`, MARGIN, this.y - 9, 9, true, MUTED);
      this.y -= 22;
    }
  }

  ensure(height: number): boolean {
    if (this.y - height >= BOTTOM) return false;
    this.newPage();
    return true;
  }

  text(value: string, x: number, baseline: number, size: number, bold = false, color: Color = INK): void {
    this.ops.push(`${color.map(n).join(' ')} rg BT /${bold ? 'F2' : 'F1'} ${n(size)} Tf ${n(x)} ${n(baseline)} Td ${pdfGlyphs(value, bold)} Tj ET`);
  }

  rect(x: number, top: number, width: number, height: number, color: Color): void {
    this.ops.push(`${color.map(n).join(' ')} rg ${n(x)} ${n(top - height)} ${n(width)} ${n(height)} re f`);
  }

  rule(top: number, color: Color = RULE): void {
    this.ops.push(`${color.map(n).join(' ')} RG 0.6 w ${n(MARGIN)} ${n(top)} m ${n(MARGIN + CONTENT_WIDTH)} ${n(top)} l S`);
  }

  /** Label/value pairs laid out left to right, wrapping onto new rows. */
  pairs(items: Array<[string, string]>, valueSize: number, valueBold: boolean, compact = false): void {
    let x = MARGIN;
    // Compact pairs (e.g. per-ingredient totals) show the label as a bold name, like the preview.
    const labelSize = compact ? 9 : 6.5;
    const rowHeight = labelSize + 1 + valueSize + 8;
    this.ensure(rowHeight);
    for (const [rawLabel, value] of items) {
      const label = compact ? rawLabel : rawLabel.toUpperCase();
      const safeValue = pdfSafeText(value).replace(/\n/g, ' · ');
      const width = Math.max(textWidth(label, labelSize, true), textWidth(safeValue, valueSize, valueBold)) + 26;
      if (x > MARGIN && x + width > MARGIN + CONTENT_WIDTH) {
        x = MARGIN;
        this.y -= rowHeight;
        this.ensure(rowHeight);
      }
      this.text(label, x, this.y - labelSize + 0.5, labelSize, true, compact ? INK : MUTED);
      this.text(safeValue, x, this.y - labelSize - 2 - valueSize, valueSize, valueBold);
      x += width;
    }
    this.y -= rowHeight;
  }

  paragraph(value: string, size = 9): void {
    for (const line of wrapText(value, CONTENT_WIDTH, size)) {
      this.ensure(size + 4);
      this.text(line, MARGIN, this.y - size, size, false, MUTED);
      this.y -= size + 4;
    }
  }

  table(table: ReportTable): void {
    const columns = table.headers.length;
    const natural = table.headers.map((header, index) => {
      let widest = textWidth(header.toUpperCase(), 6.5, true);
      for (const row of table.rows) {
        for (const line of pdfSafeText(row[index] ?? '').split('\n')) widest = Math.max(widest, textWidth(line, 7.5, index === 0));
      }
      // +1 pt so text measured exactly to the width does not wrap on rounding.
      return Math.min(Math.max(widest + CELL_PADDING * 2 + 1, 46), 230);
    });
    const total = natural.reduce((sum, width) => sum + width, 0);
    const widths = natural.map((width) => (width * CONTENT_WIDTH) / total);
    const headerLines = table.headers.map((header, index) => wrapText(header.toUpperCase(), widths[index] - CELL_PADDING * 2, 6.5, true));
    const headerHeight = Math.max(...headerLines.map((lines) => lines.length)) * 8 + 8;

    const drawHeader = () => {
      this.rect(MARGIN, this.y, CONTENT_WIDTH, headerHeight, HEAD_FILL);
      let x = MARGIN;
      headerLines.forEach((lines, index) => {
        lines.forEach((line, lineIndex) => this.text(line, x + CELL_PADDING, this.y - 10 - lineIndex * 8, 6.5, true, MUTED));
        x += widths[index];
      });
      this.y -= headerHeight;
      this.rule(this.y);
    };

    this.ensure(headerHeight + 20);
    drawHeader();
    for (const row of table.rows) {
      const cells = Array.from({ length: columns }, (_, index) => wrapText(row[index] ?? '', widths[index] - CELL_PADDING * 2, 7.5, index === 0));
      const rowHeight = Math.max(...cells.map((lines) => lines.length)) * 9.5 + 8;
      if (this.ensure(rowHeight)) drawHeader();
      let x = MARGIN;
      cells.forEach((lines, index) => {
        lines.forEach((line, lineIndex) => this.text(line, x + CELL_PADDING, this.y - 11 - lineIndex * 9.5, 7.5, index === 0));
        x += widths[index];
      });
      this.y -= rowHeight;
      this.rule(this.y);
    }
  }

  build(): void {
    const doc = this.doc;
    this.text("TAKOSYNC · GELO'S TAKOYAKI", MARGIN, this.y - 7, 7, true, PINK);
    this.y -= 12;
    for (const line of wrapText(doc.title, CONTENT_WIDTH, 16, true)) {
      this.text(line, MARGIN, this.y - 16, 16, true);
      this.y -= 20;
    }
    this.y -= 4;
    this.pairs(reportMetaLines(doc), 9, false);
    this.rule(this.y + 2);
    this.y -= 10;
    for (const section of doc.sections) {
      if (section.heading) {
        this.ensure(26);
        this.text(section.heading, MARGIN, this.y - 11, 11, true);
        this.y -= 18;
      }
      if (section.summary?.length) this.pairs(section.summary, section.compact ? 9 : 12, !section.compact, section.compact);
      for (const note of section.notes ?? []) this.paragraph(note);
      if (section.table) this.table(section.table);
      this.y -= 12;
    }
  }
}

/** The PDF file for a generated report, as bytes. */
export function buildReportPdf(doc: ReportDocument): Uint8Array {
  const layout = new PdfLayout(doc);
  layout.build();
  const pageCount = layout.pages.length;
  const footer = `${doc.title} · Generated ${formatReportDateTime(doc.generatedAt)}`;
  layout.pages.forEach((ops, index) => {
    ops.push(`${MUTED.map(n).join(' ')} rg BT /F1 7 Tf ${n(MARGIN)} 20 Td ${pdfGlyphs(footer, false)} Tj ET`);
    const label = `Page ${index + 1} of ${pageCount}`;
    ops.push(`BT /F1 7 Tf ${n(PAGE_WIDTH - MARGIN - textWidth(label, 7))} 20 Td ${pdfGlyphs(label, false)} Tj ET`);
  });

  return assemblePdf({
    title: doc.title,
    creator: 'TakoSync Owner Web Portal',
    width: PAGE_WIDTH,
    height: PAGE_HEIGHT,
    pages: layout.pages.map((ops) => ops.join('\n')),
  });
}

/**
 * Writes a PDF 1.4 file from page content streams that draw text with /F1
 * (regular) and /F2 (bold), the embedded Noto Sans subsets. Shared by the
 * reports and the staff sale receipt (ST-05 c7).
 */
export function assemblePdf(input: { title: string; creator: string; width: number; height: number; pages: string[] }): Uint8Array {
  // Objects: 1 catalog, 2 pages, 3 info, 4–8 regular font, 9–13 bold font, then page + content pairs.
  const objects: string[] = [];
  const pageIds = input.pages.map((_, index) => 14 + index * 2);
  objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[2] = `<< /Type /Pages /Count ${input.pages.length} /Kids [${pageIds.map((id) => `${id} 0 R`).join(' ')}] >>`;
  objects[3] = `<< /Title ${pdfTextString(input.title)} /Creator ${pdfTextString(input.creator)} /Producer (TakoSync) >>`;
  const embedded = [...fontObjects(REPORT_PDF_FONTS.regular, 4, 'TKSYNA'), ...fontObjects(REPORT_PDF_FONTS.bold, 9, 'TKSYNB')];
  input.pages.forEach((content, index) => {
    const pageId = pageIds[index];
    objects[pageId] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${n(input.width)} ${n(input.height)}] /Resources << /Font << /F1 4 0 R /F2 9 0 R >> >> /Contents ${pageId + 1} 0 R >>`;
    objects[pageId + 1] = `<< /Length ${content.length} >>\nstream\n${content}\nendstream`;
  });

  // Every character written is one byte (text is hex-encoded; the font files are
  // binary strings of 0–255), so string offsets are byte offsets.
  let file = '%PDF-1.4\n%\u00e2\u00e3\u00cf\u00d3\n';
  const offsets: number[] = [];
  for (let id = 1; id < objects.length; id += 1) {
    offsets[id] = file.length;
    file += id >= 4 && id <= 13 ? embedded[id - 4] : `${id} 0 obj\n${objects[id]}\nendobj\n`;
  }
  const xref = file.length;
  file += `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for (let id = 1; id < objects.length; id += 1) file += `${String(offsets[id]).padStart(10, '0')} 00000 n \n`;
  file += `trailer\n<< /Size ${objects.length} /Root 1 0 R /Info 3 0 R >>\nstartxref\n${xref}\n%%EOF\n`;

  const bytes = new Uint8Array(file.length);
  for (let index = 0; index < file.length; index += 1) bytes[index] = file.charCodeAt(index) & 0xff;
  return bytes;
}
